        this.sheetId = sheetId;
        this.name = name;
        this.leadId = leadId;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public Long getLeadId() {
        return leadId;
    }

    /** Move the lead to another person. */
    public void setLeadId(Long leadId) {
        this.leadId = leadId;
    }
}
